            <Inject services={[SankeyTooltip, SankeyLegend, SankeyHighlight, SankeyExport]}/>

            <SankeyNodesCollectionDirective>
              {nodes.map((node) => (<SankeyNodeDirective key={node.id} id={node.id} color={node.color}/>))}
            </SankeyNodesCollectionDirective>

            <SankeyLinksCollectionDirective>
              {links.map((link, i) => (<SankeyLinkDirective key={`${link.sourceId}-${link.targetId}-${i}`} sourceId={link.sourceId} targetId={link.targetId} value={link.value}/>))}
            </SankeyLinksCollectionDirective>
          </SankeyComponent>
        </div>


      </div>);
    }
}
export default Orientation;

const root = createRoot(document.getElementById('sample'));
root.render(<Orientation />);

